package com.safelaw.data.db

import android.util.Base64
import java.nio.ByteBuffer
import java.nio.ByteOrder

/**
 * 시연 질문을 앱과 동일한 KR-SBERT ONNX 파이프라인으로 미리 계산한 768차원 벡터입니다.
 * Base64는 little-endian float32 768개를 담으며, 실행 시 ONNX 모델을 열지 않습니다.
 */
internal object DemoQuestionEmbedding {
    val values: FloatArray by lazy {
        val bytes = Base64.decode(ENCODED_FLOAT32_LE, Base64.NO_WRAP)
        require(bytes.size == LawCaseImporter.EMBEDDING_DIMENSION * Float.SIZE_BYTES)
        val buffer = ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN)
        FloatArray(LawCaseImporter.EMBEDDING_DIMENSION) { buffer.float }
    }

    private const val ENCODED_FLOAT32_LE =
        ""
}
